theme.css:
:root {
  --background: #0c0a08;
  --foreground: #fafaf9;
  --card: rgba(255, 255, 255, 0.06);
  --card-foreground: #fafaf9;
  --popover: #17171b;
  --popover-foreground: #fafafa;
  --primary: #ffcc00;
  --primary-foreground: #1a0f05;
  --secondary: rgba(255, 255, 255, 0.09);
  --secondary-foreground: #fafaf9;
  --muted: rgba(255, 255, 255, 0.05);
  --muted-foreground: #a49c94;
  --accent: rgba(31, 170, 183, 0.18);
  --accent-foreground: #6ed6de;
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: hsl(210 40% 98%);
  --border: rgba(255, 255, 255, 0.14);
  --input: rgba(255, 255, 255, 0.18);
  --ring: #f58c24;
  --chart-1: #f58c24;
  --chart-2: #1faab7;
  --chart-3: #f9a748;
  --chart-4: #0e6a81;
  --chart-5: #c8a96f;
  --radius: 1.2rem;
  --sidebar: #101013;
  --sidebar-foreground: #fafafa;
  --sidebar-primary: #e3af35;
  --sidebar-primary-foreground: #09090b;
  --sidebar-accent: #1c1c21;
  --sidebar-accent-foreground: #fafafa;
  --sidebar-border: rgba(255, 255, 255, 0.08);
  --sidebar-ring: #e3af35;
  --font-sans: DM Sans, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: Roboto Mono, monospace;
  --shadow-color: hsl(30 20% 4%);
  --shadow-opacity: 0.45;
  --shadow-blur: 40px;
  --shadow-spread: -12px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 20px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
}

.dark {
  --background: #f2f6f7;
  --foreground: #16120e;
  --card: rgba(255, 255, 255, 0.65);
  --card-foreground: #16120e;
  --popover: #17171b;
  --popover-foreground: #fafafa;
  --primary: #ffcc00;
  --primary-foreground: #1a0f05;
  --secondary: rgba(255, 255, 255, 0.75);
  --secondary-foreground: #16120e;
  --muted: rgba(22, 18, 14, 0.04);
  --muted-foreground: #57524c;
  --accent: rgba(26, 3, 86, 0.12);
  --accent-foreground: #000150;
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: hsl(210 40% 98%);
  --border: rgba(21, 18, 14, 0.09);
  --input: rgba(21, 18, 14, 0.14);
  --ring: #f58c24;
  --chart-1: #f58c24;
  --chart-2: #0e8a95;
  --chart-3: #f9a748;
  --chart-4: #0b5065;
  --chart-5: #c8a96f;
  --radius: 1.2rem;
  --sidebar: #101013;
  --sidebar-foreground: #fafafa;
  --sidebar-primary: #e3af35;
  --sidebar-primary-foreground: #09090b;
  --sidebar-accent: #1c1c21;
  --sidebar-accent-foreground: #fafafa;
  --sidebar-border: rgba(255, 255, 255, 0.08);
  --sidebar-ring: #e3af35;
  --font-sans: DM Sans, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, monospace;
  --shadow-color: hsl(30 20% 4%);
  --shadow-opacity: 0.12;
  --shadow-blur: 40px;
  --shadow-spread: -12px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 20px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-radius: var(--radius);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-font-sans: var(--font-sans);
  --color-font-serif: var(--font-serif);
  --color-font-mono: var(--font-mono);
  --color-shadow-color: var(--shadow-color);
  --color-shadow-opacity: var(--shadow-opacity);
  --color-shadow-blur: var(--shadow-blur);
  --color-shadow-spread: var(--shadow-spread);
  --color-shadow-offset-x: var(--shadow-offset-x);
  --color-shadow-offset-y: var(--shadow-offset-y);
  --color-letter-spacing: var(--letter-spacing);
  --color-spacing: var(--spacing);
}
